"""Regenerate RESULTS.md from the result CSVs, so no number is typed by hand."""
import pathlib
import pandas as pd, numpy as np

R = pathlib.Path("results")
out = ["# Results tables",
       "",
       "Auto-generated by `scripts/13_make_results_md.py`. Every number below "
       "comes from a CSV in `results/`.", ""]


def tbl(df, cols, headers=None, fmt=None):
    headers = headers or cols
    fmt = fmt or {}
    out.append("| " + " | ".join(headers) + " |")
    out.append("|" + "|".join(["---"] * len(headers)) + "|")
    for _, r in df.iterrows():
        cells = []
        for c in cols:
            v = r[c]
            f = fmt.get(c)
            cells.append(f(v) if f else (f"{v:.4f}" if isinstance(v, float) else str(v)))
        out.append("| " + " | ".join(cells) + " |")
    out.append("")


pct = lambda v: f"{v*100:.1f}%"
ci = lambda lo, hi: f"[{lo*100:.1f}, {hi*100:.1f}]"

# --- audit ---------------------------------------------------------------
a = pd.read_csv(R / "audit_runs.csv")
task = a[a.run != 1]
out += ["## 1. Data audit", "",
        f"- {len(a)} recordings from {a.subject.nunique()} subjects were read.",
        f"- Sampling rate: " + ", ".join(f"{int(k)} Hz x{v}" for k, v in
                                         a.sfreq.value_counts().items()) + ".",
        f"- All {a.n_chan.nunique()} distinct channel counts: "
        f"{sorted(a.n_chan.unique().tolist())}.",
        f"- Task runs with the nominal 15 trials: "
        f"{int((task.n_T1 + task.n_T2 == 15).sum())}/{len(task)}.", ""]
bad = task[(task.sfreq != 160) | (task.n_T1 + task.n_T2 != 15)]
out += [f"Non-conforming task runs ({len(bad)}), by subject: "
        f"{sorted(bad.subject.unique().tolist())}.", ""]

# --- lateralisation ------------------------------------------------------
p = R / "lateralisation.csv"
if p.is_file():
    lat = pd.read_csv(p)
    lat["d"] = lat.li_T1 - lat.li_T2
    from scipy import stats
    rows = []
    for (par, band), g in lat.groupby(["paradigm", "band"]):
        t, pv = stats.ttest_1samp(g.d.dropna(), 0)
        rows.append(dict(paradigm=par, band=band, mean_d=g.d.mean(), t=t, p=pv,
                         frac_pos=(g.d > 0).mean(), n=g.d.notna().sum()))
    out += ["## 2. Which annotation is which hand", "",
            "Laterality index `LI = log10(power over left cluster / right cluster)`, "
            "8-30 Hz, 0.5-3.5 s. `d = LI(T1) - LI(T2)`. `d > 0` means T1 suppresses "
            "the **right** hemisphere more, i.e. T1 is the **left** fist.", ""]
    tbl(pd.DataFrame(rows), ["paradigm", "band", "mean_d", "t", "p", "frac_pos", "n"],
        ["paradigm", "band", "mean d", "t", "p", "subjects with d>0", "n"],
        {"mean_d": lambda v: f"{v:+.4f}", "t": lambda v: f"{v:.2f}",
         "p": lambda v: f"{v:.1e}", "frac_pos": pct, "n": lambda v: str(int(v))})

# --- model selection -----------------------------------------------------
p = R / "model_selection.csv"
if p.is_file():
    ms = pd.read_csv(p)
    ms["ci"] = [ci(a_, b_) for a_, b_ in zip(ms.pooled_lo, ms.pooled_hi)]
    out += ["## 3. Model selection (DEV subjects only)", "",
            "Leave-one-subject-out over the 35 DEV subjects. The EVAL subjects "
            "were not looked at while choosing any of this.", ""]
    tbl(ms, ["tag", "pooled_acc", "ci", "mean_sub_acc", "sd_sub_acc", "within_run", "secs"],
        ["configuration", "LOSO acc", "95% CI", "per-subject mean", "sd", "within/run", "s"],
        {"pooled_acc": pct, "mean_sub_acc": pct, "sd_sub_acc": lambda v: f"{v*100:.1f}",
         "within_run": lambda v: "-" if pd.isna(v) else pct(v),
         "secs": lambda v: f"{v:.0f}"})

# --- selection pass 2 ----------------------------------------------------
p = R / "selection2.csv"
if p.is_file():
    s2 = pd.read_csv(p)
    s2["ci"] = [ci(a_, b_) for a_, b_ in zip(s2.pooled_lo, s2.pooled_hi)]
    out += ["## 3b. Second selection pass (DEV subjects only)", "",
            "Each family tuned on its own regularisation before comparison, then "
            "band and window. Covariance-domain CSP throughout.", ""]
    for fam, g in s2.groupby("family", sort=False):
        out += [f"### {fam}", ""]
        tbl(g, ["tag", "pooled_acc", "ci", "mean_sub_acc", "secs"],
            ["configuration", "LOSO acc", "95% CI", "per-subject mean", "s"],
            {"pooled_acc": pct, "mean_sub_acc": pct, "secs": lambda v: f"{v:.0f}"})

# --- main regimes --------------------------------------------------------
p = R / "main_regimes.csv"
if p.is_file():
    mr = pd.read_csv(p)
    mr["ci"] = [ci(a_, b_) for a_, b_ in zip(mr.pooled_lo, mr.pooled_hi)]
    out += ["## 4. The headline table (EVAL subjects)", ""]
    for par in mr.paradigm.unique():
        g = mr[(mr.paradigm == par) & mr.regime.str.startswith(("A", "B", "C", "D", "E"))]
        if not len(g):
            continue
        out += [f"### {par}", ""]
        real = g[~g.shuffled].set_index("regime")
        shuf = g[g.shuffled].set_index("regime")
        j = real.join(shuf, rsuffix="_shuf").reset_index()
        tbl(j, ["regime", "pooled_acc", "ci", "mean_sub_acc", "sd_sub_acc",
                "frac_sig", "pooled_acc_shuf", "n_trials"],
            ["regime", "accuracy", "95% CI", "per-subject mean", "sd",
             "subjects > chance", "shuffled-label twin", "trials"],
            {"pooled_acc": pct, "mean_sub_acc": pct, "frac_sig": pct,
             "pooled_acc_shuf": pct, "sd_sub_acc": lambda v: f"{v*100:.1f}",
             "n_trials": lambda v: str(int(v))})
    cal = mr[mr.regime.str.startswith("F")]
    if len(cal):
        out += ["### Calibration curve (imagined)", ""]
        tbl(cal, ["regime", "pooled_acc", "ci", "mean_sub_acc", "n_trials"],
            ["regime", "accuracy", "95% CI", "per-subject mean", "trials"],
            {"pooled_acc": pct, "mean_sub_acc": pct, "n_trials": lambda v: str(int(v))})

# --- naive splits --------------------------------------------------------
p = R / "naive_splits.csv"
if p.is_file():
    nv = pd.read_csv(p)
    nv["ci"] = [ci(a_, b_) for a_, b_ in zip(nv.lo, nv.hi)]
    out += ["## 4b. What the easy splits would have told me", ""]
    tbl(nv, ["tag", "acc", "ci", "n"], ["split", "accuracy", "95% CI", "trials"],
        {"acc": pct, "n": lambda v: str(int(v))})

# --- controls ------------------------------------------------------------
p = R / "controls.csv"
if p.is_file():
    c = pd.read_csv(p)
    c["ci"] = [ci(a_, b_) for a_, b_ in zip(c.pooled_lo, c.pooled_hi)]
    out += ["## 5. Controls", ""]
    for blk, g in c.groupby("block", sort=False):
        out += [f"### {blk}", ""]
        cols = ["tag", "pooled_acc", "ci"]
        hdr = ["control", "accuracy", "95% CI"]
        if "chance" in g and g.chance.notna().any():
            cols.append("chance"); hdr.append("chance")
        tbl(g, cols, hdr, {"pooled_acc": pct, "chance": lambda v: "-" if pd.isna(v) else pct(v)})

# --- deep ----------------------------------------------------------------
p = R / "deep.csv"
if p.is_file():
    d = pd.read_csv(p)
    d["ci"] = [ci(a_, b_) for a_, b_ in zip(d.pooled_lo, d.pooled_hi)]
    out += ["## 6. EEGNet", ""]
    tbl(d, ["tag", "pooled_acc", "ci", "train_acc", "mean_sub_acc", "secs"],
        ["configuration", "test acc", "95% CI", "train acc", "per-subject mean", "s"],
        {"pooled_acc": pct, "train_acc": pct, "mean_sub_acc": pct,
         "secs": lambda v: f"{v:.0f}"})

# --- resting predictors --------------------------------------------------
p = R / "rest_vs_accuracy.csv"
if p.is_file():
    rv = pd.read_csv(p)
    out += ["## 7. Predicting who is decodable from a resting recording", "",
            f"Spearman correlations, {int(rv.n.iloc[0])} subjects, "
            f"{len(rv)} tests (Bonferroni p < {0.05/len(rv):.5f}).", ""]
    tbl(rv.head(15), ["target", "feature", "rho", "p"],
        ["target", "resting feature", "rho", "p"],
        {"rho": lambda v: f"{v:+.3f}", "p": lambda v: f"{v:.2e}"})

# --- holdout -------------------------------------------------------------
p = R / "holdout_predict.csv"
if p.is_file():
    h = pd.read_csv(p)
    out += ["## 8. End-to-end check on the 12 HOLDOUT subjects", "",
            "`predict.py` run on raw EDF files from subjects that appear nowhere "
            "else in this project.", ""]
    g = h.groupby("paradigm").agg(files=("n", "size"), trials=("n", "sum"),
                                  correct=("correct", "sum")).reset_index()
    g["acc"] = g.correct / g.trials
    tbl(g, ["paradigm", "files", "trials", "acc"],
        ["paradigm", "files", "trials", "accuracy"],
        {"acc": pct, "files": lambda v: str(int(v)), "trials": lambda v: str(int(v))})

# --- subject bias --------------------------------------------------------
p = R / "subject_bias.csv"
if p.is_file():
    sb = pd.read_csv(p)
    n = sb.n.sum()
    raw = (sb.acc_raw * sb.n).sum() / n
    cen = (sb.acc_centred * sb.n).sum() / n
    out += ["## 8b. Per-subject decision bias", "",
            f"- Subjects: {len(sb)}, trials: {int(n)}.",
            f"- True fraction of right-fist cues per subject: "
            f"{sb.frac_true_right.mean():.3f} +- {sb.frac_true_right.std():.3f}.",
            f"- Fraction the model *labels* right per subject: "
            f"{sb.frac_pred_right.mean():.3f} +- {sb.frac_pred_right.std():.3f} "
            f"(range {sb.frac_pred_right.min():.2f} to {sb.frac_pred_right.max():.2f}).",
            f"- Accuracy with the decision threshold at 0: {raw*100:.2f}%.",
            f"- Accuracy with the threshold at each subject's own median: "
            f"{cen*100:.2f}% ({(cen-raw)*100:+.2f} points).",
            f"- Mean per-subject AUC: {sb.auc.mean():.4f}.", ""]

# --- time resolved -------------------------------------------------------
p = R / "time_resolved.csv"
if p.is_file():
    t = pd.read_csv(p)
    out += ["## 9. Time-resolved decoding", "",
            f"Peak {t.pooled_acc.max()*100:.1f}% at "
            f"{t.loc[t.pooled_acc.idxmax(), 'centre_s']:+.2f} s; "
            f"pre-cue maximum "
            f"{t[t.centre_s < -0.5].pooled_acc.max()*100:.1f}%.", ""]

pathlib.Path("RESULTS.md").write_text("\n".join(out))
print("wrote RESULTS.md", len(out), "lines")
